@layer components {
  [data-skin="linear"] :where([data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"][data-chrome="panel"]) {
    --cui-chat-layout-radius: var(--radius-panel);
    --cui-chat-layout-background: var(--background);
    --cui-chat-layout-border-color: var(--border);
    --cui-chat-layout-shadow: var(--linear-shadow-control);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="chat-message"]) {
    --cui-chat-message-avatar-radius: 9999px;
    --cui-chat-message-avatar-background: var(--linear-control-bg);
    --cui-chat-message-avatar-border-color: var(--linear-rim);
    --cui-chat-message-avatar-border-width: var(--control-rim-width);
    --cui-chat-message-foreground: var(--secondary-foreground);
    --cui-chat-message-row-hover-background: var(--muted);
    --cui-chat-message-reaction-radius: 9999px;
    --cui-chat-message-reaction-background: var(--background);
    --cui-chat-message-reaction-border-color: var(--linear-chip-border);
    --cui-chat-message-reaction-border-width: var(--control-rim-width);
    --cui-chat-message-reaction-pressed-background: oklch(from var(--primary) l c h / 0.1);
    --cui-chat-message-reaction-pressed-border-color: oklch(from var(--primary) l c h / 0.5);
  }

  [data-skin="linear"] :where([data-slot="content"][data-control-family="chat-message"]) {
    font-size: var(--text-body-lg);
    line-height: 1.5rem;
    letter-spacing: -0.1px;
  }

  [data-skin="linear"] :where([data-slot="root"][data-role="user"][data-layout="bubble"][data-control-family="chat-message"]) {
    --cui-chat-message-radius: 0.625rem;
    --cui-chat-message-corner-radius: 0.625rem;
    --cui-chat-message-background: var(--card);
    --cui-chat-message-border-color: oklch(from var(--foreground) l c h / 0.08);
    --cui-chat-message-border-width: var(--control-rim-width);
    --cui-chat-message-shadow: var(--linear-shadow-control);
  }

  [data-skin="linear"] :where([data-slot="root"][data-role="assistant"][data-layout="bubble"][data-control-family="chat-message"]) {
    --cui-chat-message-background: transparent;
  }

  [data-skin="linear"] :where([data-control-ui="chat-composer"][data-slot="root"][data-control-family="chat-composer"]) {
    --composer-padding: 0.75rem;
    --cui-chat-composer-shell-radius: 0.625rem;
    --cui-chat-composer-shell-background: var(--card);
    --cui-chat-composer-shell-border-color: oklch(from var(--foreground) l c h / 0.08);
    --cui-chat-composer-shell-border-width: var(--control-rim-width);
    --cui-chat-composer-shell-shadow: var(--linear-shadow-control);
    --cui-chat-composer-input-foreground: var(--secondary-foreground);
    --cui-chat-composer-input-placeholder-foreground: var(--linear-placeholder);
    --cui-chat-composer-mention-radius: 9999px;
    --cui-chat-composer-mention-border-color: var(--linear-chip-border);
    --cui-chat-composer-mention-border-width: var(--control-rim-width);
    --cui-chat-composer-mention-background: var(--background);
  }

  [data-skin="linear"] :where([data-control-family="chat-composer"][data-slot="textarea"]),
  [data-skin="linear"] :where([data-control-family="chat-composer"][data-slot="fallback"]),
  [data-skin="linear"] :where([data-control-family="chat-composer"][data-slot="placeholder"]) {
    --padding-x: 1.125rem;
    --padding-y: 0.75rem;
    font-size: var(--text-body-lg);
    letter-spacing: -0.1px;
  }

  [data-skin="linear"] :where([data-control-family="chat-composer"][data-slot="toolbar"]) {
    --nest-radius: 9999px;
  }

  [data-skin="linear"]
    :where([data-control-family="chat-composer"][data-slot="toolbar"] [data-control-family="button"][data-icon-only="true"]) {
    --cui-button-height: 1.5rem;
    --cui-button-icon: 0.875rem;
  }

  [data-skin="linear"] :where([data-control-family="chat-composer-attachment"][data-slot="root"][data-variant]) {
    --cui-chat-composer-attachment-background: var(--card);
    --cui-chat-composer-attachment-backdrop-filter: none;
    --cui-chat-composer-attachment-shadow:
      inset 0 0 0 var(--control-rim-width) var(--cui-chat-composer-attachment-border-color), var(--linear-shadow-control);
  }

  [data-skin="linear"] :where([data-control-family="button"][data-chat-composer-attachment-remove="true"]) {
    --cui-button-foreground: var(--background);
    --cui-button-hover-foreground: var(--background);
    --cui-button-hover-background: oklch(from var(--foreground) l c h / 0.85);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="markdown"]) {
    --cui-markdown-foreground: var(--secondary-foreground);
    --cui-markdown-font-size: var(--text-body-lg);
    --cui-markdown-line-height: 1.6;
    --cui-markdown-inline-code-background: var(--muted);
    --cui-markdown-inline-code-foreground: var(--secondary-foreground);
    --cui-markdown-inline-code-radius: 0.25rem;
    --cui-markdown-blockquote-border-color: var(--linear-chip-border);
    --cui-markdown-table-cell-border-color: var(--border);
    --cui-markdown-table-header-background: transparent;
    letter-spacing: -0.1px;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="markdown-block"]) {
    --cui-markdown-block-radius: 0.625rem;
    --cui-markdown-block-background: var(--card);
    --cui-markdown-block-border-color: transparent;
    --cui-markdown-block-shadow: 0 0 0 var(--control-rim-width) var(--linear-rim), var(--linear-shadow-control);
    --cui-markdown-block-header-border-color: var(--border);
    --cui-markdown-block-icon-background: var(--muted);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="code"]) {
    --cui-code-radius: var(--radius-control);
    --cui-code-background: var(--muted);
    --cui-code-border-color: var(--border);
    --cui-code-shadow: none;
    --cui-code-header-background: transparent;
    --cui-code-text-foreground: var(--secondary-foreground);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="code-diff"]) {
    --cui-code-diff-radius: var(--radius-control);
    --cui-code-diff-background: var(--card);
    --cui-code-diff-border-color: var(--border);
    --cui-code-diff-shadow: none;
    --cui-code-diff-header-background: var(--muted);
    --cui-code-diff-header-border-color: var(--border);
    --cui-code-diff-foreground: var(--secondary-foreground);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="inline-attachment"]) {
    --cui-inline-attachment-radius: var(--radius-control);
    --cui-inline-attachment-background: var(--card);
    --cui-inline-attachment-ring-color: var(--linear-rim);
    --cui-inline-attachment-shadow: var(--linear-shadow-control);
    --cui-inline-attachment-hover-shadow: var(--linear-shadow-menu);
    --cui-inline-attachment-content-background: var(--card);
    --cui-inline-attachment-content-shadow: 0 0 0 var(--control-rim-width) var(--linear-rim);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="markdown-editor"]) {
    --cui-markdown-editor-background: var(--card);
    --cui-markdown-editor-border-color: oklch(from var(--foreground) l c h / 0.08);
    --cui-markdown-editor-radius: var(--radius-field);
    --cui-markdown-editor-code-background: var(--muted);
  }

  [data-skin="linear"]
    :where([data-control-family="chat-composer"][data-slot="shell"] [data-slot="root"][data-control-family="markdown-editor"]) {
    --cui-markdown-editor-border-width: 0px;
    --cui-markdown-editor-background: transparent;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="user-ask"]) {
    --cui-user-ask-background: var(--popover);
    --cui-user-ask-backdrop-filter: none;
    --cui-user-ask-border-color: var(--linear-popup-border);
    --cui-user-ask-shadow: var(--linear-shadow-menu);
    --cui-user-ask-option-hover-background: var(--linear-menu-highlight);
    --cui-user-ask-option-selected-background: var(--linear-menu-highlight);
    --cui-user-ask-indicator-background: var(--muted);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="tool-approval"]) {
    --cui-tool-approval-radius: 0.625rem;
    --cui-tool-approval-border-color: transparent;
    --cui-tool-approval-shadow: 0 0 0 var(--control-rim-width) var(--linear-rim), var(--linear-shadow-control);
    --cui-tool-approval-body-padding: 1rem;
    --cui-tool-approval-footer-padding: 0.75rem;
    --cui-tool-approval-footer-border-color: var(--border);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="task-list"]) {
    --cui-task-list-radius: 0.625rem;
    --cui-task-list-background: var(--card);
    --cui-task-list-border-color: transparent;
    --cui-task-list-ring-color: var(--linear-rim);
    --cui-task-list-shadow: var(--linear-shadow-control);
    --cui-task-list-item-foreground: var(--secondary-foreground);
    --cui-task-list-indicator-active-foreground: var(--primary);
    --cui-task-list-trigger-hover-background: var(--muted);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="activity"]) {
    --cui-activity-trigger-hover-background: var(--muted);
    --cui-activity-code-background: var(--muted);
  }

  [data-skin="linear"] :where([data-slot="title"][data-control-family="activity"]) {
    font-weight: 450;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="filter-bar"]) {
    --cui-filter-bar-background: var(--background);
    --cui-filter-bar-foreground: var(--secondary-foreground);
    --cui-filter-bar-border-color: var(--linear-chip-border);
    --cui-filter-bar-radius: 9999px;
    --cui-filter-bar-height: 1.5rem;
    --cui-filter-bar-hover-background: var(--linear-control-hover);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="inline-citation"]) {
    --cui-inline-citation-trigger-background: var(--background);
    --cui-inline-citation-trigger-border-color: var(--linear-chip-border);
    --cui-inline-citation-trigger-hover-background: var(--linear-control-hover);
    --cui-inline-citation-quote-background: var(--muted);
    --cui-inline-citation-navigation-background: var(--muted);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="source-badge"]) {
    --cui-source-badge-hover-background: var(--linear-control-hover);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="context"]) {
    --cui-context-track-fill: var(--linear-switch-off);
    --cui-context-segment-tool-fill: var(--primary);
  }
}

@layer components {
  [data-skin="linear"] :where([data-control-family="button"][data-control="true"]) {
    --cui-button-radius: var(--nest-radius, 9999px);
    --cui-button-gap: 0.375rem;
    --cui-button-icon: 1rem;
    --cui-button-padding-inline: 0.75rem;
    --cui-button-icon-padding-inline: 0.625rem;
    --cui-button-press-scale: 1;
    --cui-button-foreground: var(--muted-foreground);
    --cui-button-hover-background: var(--linear-control-hover);
    --cui-button-hover-foreground: var(--secondary-foreground);
    --cui-button-active-background: var(--linear-control-selected);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--linear-control-selected);
    --cui-button-open-background: var(--linear-control-hover);
    transition-property: scale, translate, background-color, color, box-shadow;
  }

  [data-skin="linear"] :where([data-control-family="button"][data-control="true"][data-size="xs"]) {
    --cui-button-gap: 0.25rem;
    --cui-button-icon: 0.875rem;
    --cui-button-padding-inline: 0.5rem;
    --cui-button-icon-padding-inline: 0.375rem;
    --cui-button-font-size: var(--text-label);
  }

  [data-skin="linear"] :where([data-control-family="button"][data-control="true"][data-size="sm"]) {
    --cui-button-icon: 0.875rem;
    --cui-button-padding-inline: 0.625rem;
    --cui-button-icon-padding-inline: 0.5rem;
    --cui-button-font-size: var(--text-body);
  }

  [data-skin="linear"] :where([data-control-family="button"][data-control="true"][data-size="lg"]) {
    --cui-button-padding-inline: 0.875rem;
    --cui-button-icon-padding-inline: 0.75rem;
  }

  [data-skin="linear"] :where([data-control-family="button"][data-control="true"][data-layout="tile"]) {
    --cui-button-radius: var(--nest-radius, var(--radius-panel));
  }

  [data-skin="linear"] :where([data-control-family="button"][data-control="true"][data-variant="solid"]) {
    --cui-button-foreground: var(--primary-foreground);
    --cui-button-hover-background: var(--linear-primary-hover);
    --cui-button-hover-foreground: var(--primary-foreground);
    --cui-button-press-background: var(--linear-primary-hover);
    --cui-button-active-background: var(--primary);
    --cui-button-active-foreground: var(--primary-foreground);
    --cui-button-active-hover-background: var(--linear-primary-hover);
    --cui-button-shadow: var(--linear-shadow-control);
  }

  [data-skin="linear"] :where([data-control-family="button"][data-control="true"][data-tone="danger"][data-variant="solid"]) {
    --cui-button-foreground: var(--destructive-foreground);
    --cui-button-hover-background: oklch(from var(--destructive) calc(l - 0.05) c h);
    --cui-button-hover-foreground: var(--destructive-foreground);
    --cui-button-press-background: oklch(from var(--destructive) calc(l - 0.05) c h);
    --cui-button-active-background: var(--destructive);
    --cui-button-active-hover-background: oklch(from var(--destructive) calc(l - 0.05) c h);
  }

  [data-skin="linear"] :where([data-control-family="button"][data-control="true"][data-variant="surface"]) {
    --cui-button-background: var(--linear-control-bg);
    --cui-button-foreground: var(--secondary-foreground);
    --cui-button-hover-background: var(--linear-control-hover);
    --cui-button-shadow: 0 0 0 var(--control-rim-width) var(--linear-rim), var(--linear-shadow-control);
    --cui-button-hover-shadow: 0 0 0 var(--control-rim-width) var(--linear-rim-hover), var(--linear-shadow-control);
    --cui-button-active-background: var(--linear-control-selected);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--linear-control-selected);
    --cui-button-active-shadow: 0 0 0 var(--control-rim-width) var(--linear-rim);
  }

  [data-skin="linear"] :where([data-control-family="button"][data-control="true"][data-tone="danger"]:not([data-variant="solid"])) {
    --cui-button-foreground: var(--destructive-text);
    --cui-button-hover-foreground: var(--destructive-text);
  }

  [data-skin="linear"]
    :where([data-slot="root"][data-variant="inverse"][data-control-family="toolbar"] [data-control-family="button"][data-control="true"]) {
    --cui-button-background: transparent;
    --cui-button-foreground: oklch(from var(--background) l c h / 0.7);
    --cui-button-hover-background: oklch(from var(--background) l c h / 0.1);
    --cui-button-hover-foreground: var(--background);
    --cui-button-press-background: oklch(from var(--background) l c h / 0.12);
    --cui-button-active-background: var(--background);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--background);
    --cui-button-shadow: 0 0 transparent;
    --cui-button-hover-shadow: 0 0 transparent;
    --cui-button-active-shadow: 0 0 transparent;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="track-highlight"]) {
    --cui-track-highlight-background: var(--linear-menu-highlight);
    --cui-track-highlight-ring-color: transparent;
    --cui-track-highlight-shadow: none;
  }

  [data-skin="linear"] :where([data-control-family="button-group"][data-slot="root"][data-orientation="horizontal"]) {
    --cui-button-group-text-radius: 9999px;
  }

  [data-skin="linear"]
    :where(
      [data-control-family="button-group"][data-slot="root"][data-orientation="vertical"]
        [data-control-family="button"][data-control="true"]
    ) {
    --cui-button-radius: var(--nest-radius, var(--radius-control));
  }
}

@layer components {
  [data-skin="linear"] :where([data-slot="root"][data-control-family="tabs"]) {
    --cui-tabs-trigger-radius: 9999px;
    --cui-tabs-list-padding: 0rem;
    --cui-tabs-list-background: transparent;
    --cui-tabs-list-shadow: none;
    --cui-tabs-indicator-background: transparent;
    --cui-tabs-indicator-shadow: none;
    --cui-tabs-foreground: var(--muted-foreground);
    --cui-tabs-hover-foreground: var(--secondary-foreground);
    --cui-tabs-active-foreground: var(--foreground);
    --cui-tabs-border-color: var(--border);
  }

  [data-skin="linear"] :where([data-control-family="tabs"][data-slot="list"][data-variant="default"]) {
    gap: 0.5rem;
  }

  [data-skin="linear"] :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"]) {
    --cui-tabs-trigger-radius: var(--radius-control);
  }

  [data-skin="linear"]
    :where([data-control-family="tabs"][data-slot="list"][data-variant="default"] [data-control-family="tabs"][data-slot="tab"]) {
    padding-inline: 0.625rem;
    background-color: var(--linear-control-bg);
    box-shadow:
      0 0 0 var(--control-rim-width) var(--linear-rim),
      var(--linear-shadow-control);
    transition-property: background-color, color, box-shadow;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  @media (hover: hover) {
    [data-skin="linear"]
      :where(
        [data-control-family="tabs"][data-slot="list"][data-variant="default"]
          [data-control-family="tabs"][data-slot="tab"]:hover:not([data-disabled], [data-active])
      ) {
      background-color: var(--linear-control-hover);
      box-shadow:
        0 0 0 var(--control-rim-width) var(--linear-rim-hover),
        var(--linear-shadow-control);
    }
  }

  [data-skin="linear"]
    :where(
      [data-control-family="tabs"][data-slot="list"][data-variant="default"] [data-control-family="tabs"][data-slot="tab"][data-active]
    ) {
    background-color: var(--linear-control-selected);
    box-shadow: 0 0 0 var(--control-rim-width) var(--linear-rim);
  }

  [data-skin="linear"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: var(--nest-radius, var(--radius-field));
    --cui-field-background: var(--card);
    --cui-field-hover-background: var(--card);
    --cui-field-border-color: var(--input);
    --cui-field-shadow: 0 0 transparent;
    --cui-field-affordance-hover-background: var(--linear-control-hover);
    --cui-field-font-weight: 400;
  }

  [data-skin="linear"] :where([data-control-family="field"][data-control="true"][data-size="sm"]) {
    --cui-field-font-size: var(--text-body);
  }

  [data-skin="linear"] :where([data-control-family="field"][data-control="true"]:focus-within) {
    --cui-field-border-color: var(--linear-input-focus-border);
  }

  [data-skin="linear"] :where([data-control-family="field"][data-control="true"])::placeholder,
  [data-skin="linear"]
    :where([data-control-family="field"][data-control="true"] [data-control-family="field"][data-slot="input"])::placeholder {
    color: var(--linear-placeholder);
  }

  [data-skin="linear"]
    :where(
      [data-control-family="field"][data-field-kind="combobox"][data-slot="input"],
      [data-control-family="field"][data-field-kind="autocomplete"][data-slot="input"],
      [data-control-family="field"][data-field-kind="number-field"][data-slot="input"],
      [data-control-family="field"][data-field-kind="number-field"][data-slot="group"],
      [data-control-family="field"][data-field-kind="input-otp"][data-slot="slot"]
    ) {
    --cui-field-font-weight: 400;
  }

  [data-skin="linear"] :where([data-control-family="field"][data-field-kind="combobox"][data-slot="input-group"]) {
    --cui-field-affordance-background: transparent;
  }

  [data-skin="linear"]
    :where(
      [data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"],
      [data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]
    ) {
    border-color: var(--input);
    border-inline-width: var(--control-rim-width);
  }

  [data-skin="linear"]
    :where(
      [data-control-family="field"][data-field-kind="select"][data-slot="trigger"],
      [data-control-family="field"][data-field-kind="native-select"][data-control="true"]
    ) {
    --cui-field-background: var(--linear-control-bg);
    --cui-field-hover-background: var(--linear-field-hover);
    --cui-field-foreground: var(--secondary-foreground);
    --cui-field-border-color: transparent;
    --cui-field-shadow: 0 0 0 var(--control-rim-width) var(--linear-rim), var(--linear-shadow-control);
    --cui-field-padding-inline: 0.625rem;
    transition-property: background-color, box-shadow, color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  [data-skin="linear"]
    :where(
      [data-control-family="field"][data-field-kind="select"][data-slot="trigger"][data-size="md"],
      [data-control-family="field"][data-field-kind="native-select"][data-control="true"][data-size="md"]
    ) {
    --cui-field-height: 1.875rem;
  }

  @media (hover: hover) {
    [data-skin="linear"]
      :where(
        [data-control-family="field"][data-field-kind="select"][data-slot="trigger"],
        [data-control-family="field"][data-field-kind="native-select"][data-control="true"]
      ):hover:not(:disabled, [data-disabled]) {
      --cui-field-shadow: 0 0 0 var(--control-rim-width) var(--linear-rim-hover), var(--linear-shadow-control);
    }
  }

  :is(.dark [data-skin="linear"], [data-skin="linear"].dark)
    :where(
      [data-control-family="field"][data-field-kind="select"][data-slot="trigger"],
      [data-control-family="field"][data-field-kind="native-select"][data-control="true"]
    ) {
    --cui-field-background: var(--linear-control-hover);
  }

